with source as (

    select * from {{ source('ripple_raw', 'FED_IRS_REVOCATION') }}

),

renamed as (

    select
        "EIN" as ein,
        "LEGAL_NAME" as legal_name,
        "DBA_NAME" as dba_name,
        "ORG_ADDRESS" as org_address,
        "CITY" as city,
        "STATE" as state,
        "ZIP_CODE" as zip_code,
        "COUNTRY" as country,
        "EXEMPTION_TYPE" as exemption_type,
        "REVOCATION_DATE" as revocation_date,
        "REVOCATION_POSTING_DATE" as revocation_posting_date,
        "EXEMPTION_REINSTATEMENT_DATE" as exemption_reinstatement_date,
        _INGESTED_AT as _loaded_at,
        'https://www.irs.gov/charities-non-profits/tax-exempt-organization-search-bulk-data-downloads' as _source_url,
    'ENT_' || LEFT(MD5('EIN' || '|' || (CASE WHEN LENGTH(UPPER(REGEXP_REPLACE(TO_VARCHAR("EIN"), '[^0-9A-Za-z]', ''))) = 0 OR LENGTH(UPPER(REGEXP_REPLACE(TO_VARCHAR("EIN"), '[^0-9A-Za-z]', ''))) > 9 OR LPAD(UPPER(REGEXP_REPLACE(TO_VARCHAR("EIN"), '[^0-9A-Za-z]', '')), 9, '0') = REPEAT('0', 9) THEN NULL ELSE LPAD(UPPER(REGEXP_REPLACE(TO_VARCHAR("EIN"), '[^0-9A-Za-z]', '')), 9, '0') END)), 16) as spine_entity_id  -- joins LIBRARY_META."CONNECT".ENTITY_GOLDEN.ENTITY_ID

    from source

)

